import{_ as t,H as o,f as d,i as s}from"./chunks/framework.q8faWwAa.js";const u=JSON.parse('{"title":"Upgrading to v4","description":"","frontmatter":{},"headers":[],"relativePath":"guide/migration-guide-v4.md","filePath":"guide/migration-guide-v4.md"}'),a={name:"guide/migration-guide-v4.md"};function i(n,e,r,c,l,p){return o(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="upgrading-to-v4" tabindex="-1">Upgrading to v4 <a class="header-anchor" href="#upgrading-to-v4" aria-label="Permalink to &quot;Upgrading to v4&quot;">​</a></h1><p>This is the migration guide for upgrading from <strong>v3</strong> to <strong>v4</strong>. v4 modernizes the toolchain (ESM-only, Node ≥ 22, new bundler / test runner / linter) <strong>and</strong> moves the typeorm peer-dep to <code>^1.0.0</code>. TypeORM <code>0.3.x</code> is no longer supported — stay on <code>typeorm-extension</code> v3 if you need it.</p><h2 id="breaking-changes" tabindex="-1">Breaking Changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking Changes&quot;">​</a></h2><h3 id="package-is-esm-only" tabindex="-1">Package is ESM-only <a class="header-anchor" href="#package-is-esm-only" aria-label="Permalink to &quot;Package is ESM-only&quot;">​</a></h3><p><code>typeorm-extension</code> no longer publishes a CommonJS build. Consumers must use Node ≥ 22 (which supports <code>require(esm)</code> for legacy CJS code paths).</p><table tabindex="0"><thead><tr><th></th><th>v3</th><th>v4</th></tr></thead><tbody><tr><td><code>main</code></td><td><code>dist/index.cjs</code></td><td><code>dist/index.mjs</code></td></tr><tr><td><code>module</code></td><td><code>dist/index.mjs</code></td><td>—</td></tr><tr><td><code>types</code></td><td><code>dist/index.d.ts</code></td><td><code>dist/index.d.mts</code></td></tr></tbody></table><h3 id="single-cli-binary" tabindex="-1">Single CLI binary <a class="header-anchor" href="#single-cli-binary" aria-label="Permalink to &quot;Single CLI binary&quot;">​</a></h3><p>The dual binary scheme is gone. There is now one binary, <code>typeorm-extension</code>, backed by <code>bin/cli.mjs</code>.</p><table tabindex="0"><thead><tr><th>v3</th><th>v4</th></tr></thead><tbody><tr><td><code>typeorm-extension</code> → <code>bin/cli.cjs</code></td><td><code>typeorm-extension</code> → <code>bin/cli.mjs</code></td></tr><tr><td><code>typeorm-extension-esm</code> → <code>bin/cli.mjs</code></td><td><em>removed</em></td></tr></tbody></table><p>Update any <code>package.json</code> scripts:</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- &quot;db:create&quot;: &quot;ts-node ./node_modules/typeorm-extension/bin/cli.cjs db:create&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ &quot;db:create&quot;: &quot;tsx ./node_modules/typeorm-extension/bin/cli.mjs db:create&quot;</span></span></code></pre></div><p>You can use any TypeScript-aware loader (<code>tsx</code>, Node&#39;s <code>--experimental-strip-types</code>, <code>bun</code>, …) — <code>ts-node</code> is no longer recommended because its ESM mode requires extra setup.</p><p><code>ts-node</code> and <code>tsx</code> are detected automatically, so file paths are kept as-is (no <code>src</code> → <code>dist</code> rewrite). For other loaders, pass <code>--preserveFilePaths</code> to get the same behaviour.</p><h3 id="minimum-node-js-version" tabindex="-1">Minimum Node.js version <a class="header-anchor" href="#minimum-node-js-version" aria-label="Permalink to &quot;Minimum Node.js version&quot;">​</a></h3><table tabindex="0"><thead><tr><th>v3</th><th>v4</th></tr></thead><tbody><tr><td><code>^20.19.0 || ^22.13.0 || ^23.5.0 || &gt;=24.0.0</code></td><td><code>&gt;=22.0.0</code></td></tr></tbody></table><h3 id="peer-dependency-typeorm" tabindex="-1">Peer dependency: TypeORM <a class="header-anchor" href="#peer-dependency-typeorm" aria-label="Permalink to &quot;Peer dependency: TypeORM&quot;">​</a></h3><table tabindex="0"><thead><tr><th>v3</th><th>v4</th></tr></thead><tbody><tr><td><code>typeorm ~0.3.0</code></td><td><code>typeorm ^1.0.0</code></td></tr></tbody></table><p>TypeORM <code>0.3.x</code> is <strong>not</strong> supported on <code>typeorm-extension</code> v4+. Pick the row that fits you:</p><ul><li>Already on TypeORM <code>1.0</code>: upgrade to <code>typeorm-extension</code> v4.</li><li>Still on TypeORM <code>0.3.x</code>: stay on <code>typeorm-extension</code> v3 until you can migrate the rest of your app to TypeORM <code>1.0</code>.</li></ul><p>The TypeORM 1.0 upstream changes that affect <code>typeorm-extension</code> consumers:</p><ul><li><strong><code>sqlite</code> driver removed</strong> — TypeORM 1.0 dropped the <code>sqlite</code> package; only <code>better-sqlite3</code> is supported. <code>typeorm-extension</code> follows suit and only handles <code>better-sqlite3</code> in <code>createDatabase</code> / <code>dropDatabase</code> / <code>TYPEORM_CONNECTION</code>.</li><li><strong>MongoDB</strong>: requires <code>mongodb</code> <code>^7.0.0</code>.</li><li><strong>MySQL</strong>: only the <code>mysql2</code> package is supported (the legacy <code>mysql</code> package is removed).</li><li><strong>Node.js</strong>: TypeORM 1.0 requires Node <code>^20.19.0 || ^22.13.0 || &gt;=24.11.0</code>. <code>typeorm-extension</code> v4 already requires Node <code>&gt;=22.0.0</code>.</li></ul><p>See the <a href="https://typeorm.io/docs/releases/1.0/release-notes/" target="_blank" rel="noreferrer">TypeORM 1.0 release notes</a> for the full list of upstream breaking changes.</p><h3 id="seeder-execution-no-longer-registers-the-data-source-globally" tabindex="-1">Seeder execution no longer registers the data source globally <a class="header-anchor" href="#seeder-execution-no-longer-registers-the-data-source-globally" aria-label="Permalink to &quot;Seeder execution no longer registers the data source globally&quot;">​</a></h3><p>In v3, constructing a <code>SeederExecutor</code> (which <code>runSeeder</code> / <code>runSeeders</code> do internally) registered the given data source under the <code>default</code> alias as a side effect — silently repointing what <code>useDataSource()</code> returns everywhere else in the process.</p><p>In v4, the executor leaves the data-source registry untouched. Factories resolved through the <code>factoryManager</code> passed to <code>Seeder.run()</code> are bound to the executor&#39;s data source, so factory <code>save()</code> / <code>saveMany()</code> still persist into the seeded database. If other code relies on <code>useDataSource()</code> returning the seeded data source, register it explicitly:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { runSeeders, setDataSource } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;typeorm-extension&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setDataSource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dataSource); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// was implicit in v3</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> runSeeders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dataSource);</span></span></code></pre></div><h2 id="internal-toolchain-no-consumer-impact" tabindex="-1">Internal Toolchain (no consumer impact) <a class="header-anchor" href="#internal-toolchain-no-consumer-impact" aria-label="Permalink to &quot;Internal Toolchain (no consumer impact)&quot;">​</a></h2><p>For contributors only:</p><ul><li>Bundler: Rollup + swc → <strong><a href="https://tsdown.dev" target="_blank" rel="noreferrer">tsdown</a></strong> (rolldown + oxc)</li><li>Test runner: Jest + ts-jest → <strong>Vitest 4</strong> with <code>unplugin-swc</code></li><li>Linter: ESLint 8 + <code>@tada5hi/eslint-config-typescript</code> → <strong>ESLint 10</strong> flat config + <code>@tada5hi/eslint-config</code> v2</li><li>Publish action: <code>workspaces-publish</code> → <strong><a href="https://github.com/tada5hi/monoship" target="_blank" rel="noreferrer"><code>tada5hi/monoship@v2</code></a></strong></li><li>Husky 9 hooks now in v9 format (no shebang, no <code>_/husky.sh</code> source)</li><li>TypeScript 5 → <strong>TypeScript 6</strong></li></ul>`,29)])])}const g=t(a,[["render",i]]);export{u as __pageData,g as default};
